--目前木桩在用
function UIFightTeamDialog:ReSelectLevel(levelId, datas)
    local argument = self.controller.Argument.parameters
    if not argument then return end
    argument.levelId = levelId
    argument.datas = datas
    if fightPreWarMgr then
        fightPreWarMgr:SetFightTeamArgs(argument)
    end
    self.curLevelId = checkNumber(argument.levelId)    -- 关卡ID
    self.datas = checkTable(argument.datas)    -- 关卡ID
    self:FillLeftInfo(argument)
end

function UIFightTeamDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then return end
    if fightPreWarMgr then 
        fightPreWarMgr:SetFightTeamArgs(argument)
    end
    self.curLevelId = checkNumber(argument.levelId)    -- 关卡ID
    self.isThreeTripleMode = checkBool(argument.isThreeTripleMode)
    self._teamIndex = argument.teamIndex -- 队伍下标
    self._maxTeamMember = QuestConfMgr:GetInstance():GetTeamMemberNum(self.curLevelId, self._teamIndex)
    self._teamIndex = self._teamIndex or teamComponent:GetSelectedTeamIndexByQuestId(self.curLevelId)
    self._upBuffData = argument.upBuffData  -- 通用的增益buff数据
    self._upGroup = checkTable(argument.upGroup) -- 通用增益卡牌
    self.freeTimesRemain = checkNumber(argument.freeTimesRemain)  -- 免费挑战次数
    self.curLevelVo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)   --关卡配置
    self._activityUuid = checkNumber(argument.activityUuid)
    self._eventId = checkNumber(argument.eventId)
    self._patrolMaze = argument.patrolMaze
    if argument.routerType then
        self._routerType = argument.routerType
    end

    if self.curLevelId ~= Constants.SpecialQuestId.LadderStruggleId
    and self.curLevelId ~= Constants.SpecialQuestId.LadderStruggleSingleId 
    and self.curLevelId ~= Constants.SpecialQuestId.ClubGVGId
    and self.curLevelId ~= Constants.SpecialQuestId.FriendPVPId then
        if not self.curLevelVo then
            return
        end
        
        self.curLevelType = GoodsUtils.GetIdType(self.curLevelId, Constants.IDArea.Quests)     --关卡类型
        if self.curLevelType == Constants.IDType.None then
            return
        end
    end

    self._isShowCatBall = QuestConfMgr:GetInstance():IsShowCatBall(self.curLevelId, self.curLevelType)

    self._isHideFetters = QuestConfMgr:GetInstance():IsHideFetters(self.curLevelId, self.curLevelType)

    self:InitAutoData()

    print("self.curLevelType", self.curLevelType, self.curLevelId)
    local teamTab = {}
    if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
        self._isOwn = (checkNumber(argument.isOwn) == 1)     --是否是自己
        if self._isOwn then
            teamTab = RegionQuestMgr:GetInstance():GetOwnTeam(true)
        else
            teamTab = RegionQuestMgr:GetInstance():GetOtherTeam(true)
        end
        self._maxTeamMember = RegionQuestMgr:GetInstance():GetOwnTeamNum()
    else
        teamTab = teamComponent:GetTeamByQuestId(self.curLevelId, self._teamIndex)
    end

    if self.curLevelType == Constants.IDType.QuestWorldBoss then
        self._maxTeamMember = Constants.WorldBossTeamCount
    elseif self.curLevelType == Constants.IDType.ActivityCrisis then
        self.entryData = ActivityCrisisUtils.GetActivityCrisisMgr():GetEntryData()
        self._maxTeamMember = ActivityCrisisUtils.GetMaxTeamMember(self.entryData)
    end

    CfUtils.SetActive(self.CardsLimitRemind,self.curLevelType == Constants.IDType.ClubBoss or self.curLevelType == Constants.IDType.Fairyland)
    if self.curLevelType == Constants.IDType.Fairyland then
        CfUtils.FillText(self.CardsLimitText, localize("每个角色只能打一次"))
    else
        CfUtils.FillText(self.CardsLimitText, localize("社团特训中，本日内禁止上阵同一战斗员卡牌"))
    end

    teamTab = self:CheckCardLimit(teamTab)
    self:FillTeamInfo(teamTab)
    self:FillLeftInfo(argument)
    self:InitFilter()
    self:FillRoleUpInfo(teamTab)
    -- CfUtils.SetActive(self.InfoGroup, false)
end

function UIFightTeamDialog:FillRoleUpInfo(teamTab)
    local data = checkTable(self._upGroup)
    CfUtils.SetActive(self.RoleUpDetails.gameObject, false)
    if table.count(data) > 0 then
        CfUtils.SetActive(self.BtnRoleUpRemind.gameObject,true)
        local isActive = self:IsHaveUpCard(data, teamTab)
        CfUtils.SetUISwitchImage(self.ImgSymbol,isActive and 2 or 1)
        UICommonUtils.RefreshCommonUpGroup(self.CommRoleBonusLayoutGroup, data, true,{{id = Constants.UITypeIds.UIFightTeamChoose}})
    else
        CfUtils.SetActive(self.BtnRoleUpRemind.gameObject,false)
    end
end

function UIFightTeamDialog:IsHaveUpCard(data, teamTab)
    for k, v in pairs(teamTab) do
        for i, j in pairs(data) do
            if v.cardId == j.refId then
                return true
            end
        end
    end
    return false
end

