function UIFightTeamDialog:FillBg()
    if self.curLevelId == Constants.SpecialQuestId.LadderStruggleId
    or self.curLevelId == Constants.SpecialQuestId.LadderStruggleSingleId
    or self.curLevelId == Constants.SpecialQuestId.ClubGVGId
    or self.curLevelId == Constants.SpecialQuestId.Mirror
    or self.curLevelId == Constants.SpecialQuestId.FriendPVPId then
        return
    end
    local sceneId = checkNumber(self.curLevelVo.SceneId)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting270, "BattleSceneVo", sceneId)
    if vo then
        local path = vo.teamBg
        CfUtils.FillImage(self.controller.gameObject.transform:Find("BgContainer/BG"), path)
    end
    --[[
    local path = "Arts/Textures/TeamBg/team_bg_001.png"
    if sceneId >= 1 and sceneId <= 7 then
        path = string.format("Arts/Textures/TeamBg/team_bg_00%d.png", sceneId)
    end
    ]]
end

--绘制左边的信息
function UIFightTeamDialog:FillLeftInfo(argument)
    if self.curLevelType == Constants.IDType.QuestMaze then     --迷宫
        local MazeMgr = import('Game.Maze.MazeMgr')
        local isBoss = table.count(MazeMgr:GetInstance().currentInfo) == 1 and checkNumber(MazeMgr:GetInstance().currentInfo["1"].type) == 3
        KTool.SetActive(self.MonsterTitleNode, isBoss)
        self._mazePoint = argument.point
        self:FillMazeLeftInfo()
        KTool.SetActive(self.GiveupNode, true)
        CfUtils.FillText(self.MazeGiveUpNum, MazeMgr:GetInstance():GetEscapeTime())
    elseif self.curLevelType == Constants.IDType.QuestPatrolMaze then     --海外夜巡迷宫
        self:FillPatrolMazeLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestGachaCoin                        --抽卡普通
            or self.curLevelType == Constants.IDType.QuestGachaCoinChallenge then     --抽卡挑战
        self._bossHpPercent = checkNumber(argument.bossHpPercent)  -- boss血量百分比
        self:FillMazeLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestTower then   --爬塔
        self:FillTowerLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestTrail then   --试炼
        self._conditionParas = {}
        if argument and argument.conditions then
            local conditions = argument.conditions
            local keys = sortByKey(conditions)
            for k, v in pairs(keys) do
                table.insert(self._conditionParas, {id = v, num = conditions[v]})
            end
        end
        self:FillTrailLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestSeniorEquipCopy then   --高级装备副本
        self:FillCommonLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestBambooChanllenge then   --竹林挑战副本
        self._activityUuid = checkNumber(argument.activityUuid)
        self._buffDataMap = checkTable(argument.buffGroupIds)
        self:FillBambooLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestDirectionalFight then   --定向作战
        self:FillDirectionalInfo()
    elseif self.curLevelType == Constants.IDType.QuestMediumPT then   --中型pt本
        self._activityUuid = checkNumber(argument.activityUuid)
        self:FillCommonLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestCardExperience or self.curLevelType == Constants.IDType.ActivityQuestSkinExperience then   --武装体验
        self._activityUuid = checkNumber(argument.activityUuid)
        self:FillCommonLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestTrainField then   --木桩
        self.datas = checkTable(argument.datas)
        self:FillTrainFieldLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestTalent then   --天赋
        local buffVos = {} 
        if self._upBuffData then
            for _, v in pairs(self._upBuffData) do
                for k, vo in pairs(v) do
                    table.insert(buffVos, vo)
                end
            end
        end
        self._buffDataMap = buffVos
        self:FillTalentLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestNightCatTower or self.curLevelType == Constants.IDType.QuestNightCatBoss then   --暗夜猫
        self:FillNightCatLeftInfo() 
    elseif self.curLevelType == Constants.IDType.QuestBossChallenge then -- boss挑战
        self._activityUuid = checkNumber(argument.activityUuid)
        self._scheduleId = checkNumber(argument.scheduleId)
        self:FillCommonLeftInfo()
    elseif self.curLevelType == Constants.IDType.QuestHalloween then   --暗夜猫
        self._activityUuid = checkNumber(argument.activityUuid)
        self:FillHalloweenLeftInfo() 
    elseif AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then   --歼灭战
        self:FillQuestAnnihilationInfo()
    elseif self.curLevelId == Constants.SpecialQuestId.LadderStruggleId
    or self.curLevelId == Constants.SpecialQuestId.LadderStruggleSingleId then
        self:HideLadderStruggleDontNeed()
    elseif self.curLevelId == Constants.SpecialQuestId.FriendPVPId then
        self:FillFriendPVPInfo()
    else
        self:FillCommonLeftInfo()
    end

    self:FillConditions()
end

function UIFightTeamDialog:InitFilter()
    if teamComponent:IsUseOldTeams(self.curLevelId) then
        CfUtils.SetActive(self.CommonFilterNode, false)
        return
    elseif teamComponent:IsUseTempTeam(self.curLevelId) then
        CfUtils.SetActive(self.CommonFilterNode, false)
        return 
    end

    CfUtils.SetActive(self.CommonFilterNode, true)
    ---@type UICommonFilterMB
    local filterScr = CfUtils.GetLuaScr(self.CommonFilterNode, Constants.UILuaTablePath.ComFilterMB)
    filterScr:SetPageType(Constants.UIFilterPageType.DropDown)
    
    local typeData = {}
    local teamInfo = teamComponent:GetTeamInfoByQuestId(self.curLevelId)
    for i = 1, Constants.TeamsUpLimit do
        if teamInfo[i] then
            table.insert(typeData, {typeDesc = teamInfo[i].name or teamComponent:GetEmptyTeamName(i)})
        else
            table.insert(typeData, {typeDesc = teamComponent:GetEmptyTeamName(i)})
        end
    end

    filterScr:InitSortTypeData(typeData)
    filterScr:SetCallback({}, function()
        local selectIndex  = filterScr.selectIndex
        if selectIndex ~= teamComponent:GetSelectedTeamIndexByQuestId(self.curLevelId) then
            teamComponent:SetSelectedTeamIndexByQuestId(selectIndex, self.curLevelId)
            self._teamIndex = selectIndex

            local teamTab = {}
            --if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
            --    self._isOwn = (checkNumber(argument.isOwn) == 1)     --是否是自己
            --    if self._isOwn then
            --        teamTab = RegionQuestMgr:GetInstance():GetOwnTeam(true)
            --    else
            --        teamTab = RegionQuestMgr:GetInstance():GetOtherTeam(true)
            --    end
            --    self._maxTeamMember = RegionQuestMgr:GetInstance():GetOwnTeamNum()
            --else
                teamTab = teamComponent:GetTeamByQuestId(self.curLevelId, self._teamIndex)
            --end
            self:CheckCardLimit(teamTab, true)
            self:OnRefreshTeamCat()
        end
    end)
    filterScr:SetStyleType(1)
    local teamIndex = teamComponent:GetSelectedTeamIndexByQuestId(self.curLevelId)
    filterScr.selectIndex = teamIndex
    self._teamIndex = teamIndex
    filterScr:RefreshUI()
end

function UIFightTeamDialog:OnBtnContinuousFight()
