    if isOpen then
        teamComponent:SetIsOpenContinue(false)
        CfUtils.PlayAnimation(self.BtnContinuousFight.transform:Find("AnimRoot"), "BtnContinuousFight_OffDefault")
    else
        UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamContinuousFightPopupDialog, parameters = {questId = self.curLevelId} },  {
            --{id = Constants.UITypeIds.UIFightTeamChoose}
        })
    end
end

