end

function UIFightTeamDialog:OnClickCloseClick()
    CfUtils.SetActive(self.RoleUpDetails.gameObject, false)
end


function UIFightTeamDialog:FillBtnContinuousFight()
    local isShow = teamComponent:CanUseContinueFight(self.curLevelId)
    CfUtils.SetActive(self.BtnContinuousFight, isShow)

    if isShow then
        local isOpen = teamComponent:GetIsOpenContinue()
        local name = "BtnContinuousFight_Off"
        if isOpen then
            name = "BtnContinuousFight_On"
        end

        CfUtils.PlayAnimation(self.BtnContinuousFight.transform:Find("AnimRoot"), name)
    end
end

function UIFightTeamDialog:FillConditions()
    CfUtils.SetActive(self.ConditionDiaplay, false)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)
    if not vo then
        return
    end

    vo = QuestConfMgr:GetInstance():GetQuestTeamLimitVo(vo.roleRestrictions)
    if not vo then
        return
    end
    local t = teamComponent:GetTeamByQuestId(self.curLevelId, self._teamIndex)

    local t1 = {}
    local t2 = {}

    local armT1 = {}
    local armT2 = {}

    local attrT1 = {}
    local attrT2 = {}
    
    local t1B = true
    local t2B = true

    for i = 1, 4 do
        local type = checkNumber(vo["type"..i])
        local roleId = checkInt(vo["roleId"..i])
        local armId = checkInt(vo["arm"..i])
        local attrId = checkInt(vo["attribute"..i])
        local isTrue = QuestConfMgr:GetInstance():IsTeamContentCondition(t, type, roleId, armId, attrId)
        if type == Constants.TeamLimitType.Must then
            if roleId > 0 then
                table.insert(t1, roleId)
            end
            if armId > 0 then
                table.insert(armT1, armId)
            end
            if attrId > 0 then
                table.insert(attrT1, attrId)
            end
