            or self.curLevelType == Constants.IDType.QuestExpCopy
            or self.curLevelType == Constants.IDType.QuestUpStarCopy
            or self.curLevelType == Constants.IDType.QuestMediumPT
            or self.curLevelType == Constants.IDType.QuestBambooChanllenge
            or self.curLevelType == Constants.IDType.QuestHalloween
            or self.curLevelType == Constants.IDType.QuestSeniorEquipCopy
            or self.curLevelType == Constants.IDType.QuestDaily
            or self.curLevelType == Constants.IDType.QuestMapDecryptionTracking
            or self.curLevelType == Constants.IDType.QuestMapDecryptionMap
    then
        KTool.SetActive(self.ModelThreeTimes, true)
        local canUseTripleMode = QuestConfMgr:GetInstance():IsPassAndCompleteAllCdtQuest(self.curLevelId)
        if canUseTripleMode then
            local isOpenTripleMode = KCookie.Get("isOpenTripleMode")
            if checkBool(isOpenTripleMode) then
                self.isThreeTripleMode = true
            else
                --KTool.SetActive(self.ImgHookThreeTimes, self.isThreeTripleMode)
            end
        else
            --KTool.SetActive(self.ImgHookThreeTimes, false)
        end
        self:FreshTripleModeStatus()
    else
        KTool.SetActive(self.ModelThreeTimes, false)
    end

end


