function UIFightTeamDialog:GetEnemyData()
    local t = QuestConfMgr:GetInstance():GetEnemysDataInfo(self.curLevelId)

    for i = 1, #t do
        local hpEnergyData = {}
        if self.curLevelType == Constants.IDType.QuestMaze then
            local MazeMgr = import('Game.Maze.MazeMgr')
            hpEnergyData = MazeMgr:GetInstance():GetMonstHpEnergyInfo(t[i].id)
        elseif self.curLevelType == Constants.IDType.QuestGachaCoin then                    --抽卡普通
            hpEnergyData = {
                hpPercent = checkNumber(self._bossHpPercent)
            }
        end
        t[i].hpPercent = hpEnergyData.hpPercent
        t[i].energy = hpEnergyData.energy
    end
    return t
end

--关卡条件
function UIFightTeamDialog:FillConditionNode()
    KTool.SetActive(self.FightConditionNode, true)
    ---@type UIFightTeamConditionNode
    local scr = CfUtils.GetLuaScr(self.FightConditionNode, UIFightTeamConditionNode)
    if scr then
        local t = self:GetConditionData()
        scr:Refresh(self.curLevelVo, self.curLevelId, t, self._conditionParas)
        if t then
            self.FightConditionNode.sizeDelta = Vector2(self.FightConditionNode.sizeDelta.x, 44.1 + 45 * table.count(t))

            --试炼为满足条件不让进
            if self.curLevelType == Constants.IDType.QuestTrail then
                self.isContentCondition = true
                for k, v in pairs(t) do
                    local isCompletCdt = QuestConfMgr:GetInstance():IsCompleteCondition(self.curLevelId, v.id, self._conditionParas)
                    if not isCompletCdt then
                        self.isContentCondition = false
                        break
                    end
                end
            end
        end
    end
end

