--获取条件数据
function UIFightTeamDialog:GetConditionData()
    local t
    --if self.curLevelType == Constants.IDType.QuestSeniorEquipCopy then
    --    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
    --    t = {
    --        [1] = {
    --            desc = localize("助力点上限"),
    --            num = equipQuestComp:GetCurQuestCostNum()
    --        },
    --        [2] = {
    --            desc = localize("已占用助力点"),
    --            num = teamComponent:GetCurTeamXielizhi(self.teamTab)
    --        }
    --    }
    if self.curLevelType == Constants.IDType.QuestMaze or
     self.curLevelType == Constants.IDType.QuestGachaCoin or
     self.curLevelType == Constants.IDType.QuestGachaCoinChallenge then
        t = {
            [1] = {
                desc = localize("击败团队所有人"),
            }
        }
    elseif self.curLevelType == Constants.IDType.QuestTower then 
        t = {}
        local buffData = self:GetTowerBuffData()
        for i = 1, #buffData do
            local buffVo =  CfUtils.GetCfLine(AutoIds.IdSetting573, buffData[i].buffId)
            local str = ""
            if checkNumber(buffData[i].targetId) == 202 then
                str = localize("我方")
            elseif checkNumber(buffData[i].targetId) == 102 then
                str = localize("敌方")
            end
            local name, desc = CardProgressionSkillUtils.ParseSkillBuffDesc(buffData[i].buffId)
            table.insert(t, {
                desc = str..desc
            })
        end
    elseif self.curLevelType == Constants.IDType.QuestTalent then 
        t = {}
        local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
        local buffIds = talentQuestComponent:GetCurBuffIds()
        local _t = {}
        for k, v in pairs(buffIds) do
            table.insert(_t, {
                id = checkNumber(k),
                buffId = checkNumber(v)
            })
        end
        table.sort(_t, function(a, b)
            return a.id < b.id
        end)
        for k, v in pairs(_t) do
            local vo = QuestConfMgr:GetInstance():GetTalentBuffVo(v.buffId)
            if vo then
                vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(vo.buffId)
                if vo then
                    table.insert(t, {
                        desc = vo.desc
                    })
                end
            end
        end
    elseif self.curLevelType == Constants.IDType.QuestMain or self.curLevelType == Constants.IDType.QuestMainChallenge then 
        --[[
        local vos = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.curLevelId)
        local BattlingCombatLevelMgr = import("Game.UI.UIBattling.BattleCombat.BattlingCombatLevelMgr")
        local data = BattlingCombatLevelMgr:UpdateQuestConditionData(self.curLevelId, #vos)
        t = {}
        for k, v in pairs(data) do
            table.insert(t, {
                desc = v.desc,
            })
        end
        ]]
        local _
        _, t = QuestConfMgr:GetInstance():GetQuestConditions(self.curLevelId, nil, self._conditionParas)
    elseif self.curLevelType == Constants.IDType.QuestNightCatTower or self.curLevelType == Constants.IDType.QuestNightCatBoss then    --暗夜猫
        ---@type NightCatQuestComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NightCatQuestComponent)
        local buffIds = comp:GetEquipBuffInfo()
        local tableName = string.format("%sIDGroup", AutoIds.IdSetting2731)
        t = {}

        for k, v in pairs(buffIds) do
            if checkNumber(v) > 0 then
                local level = comp:GetBuffLevel(v)
                local effectId = CfUtils.GetStringIdGroupData(tableName, v.."_"..level)
                
                local vo = QuestConfMgr:GetInstance():GetNightCatGoodsEffectVo(effectId)
                if vo then
                    table.insert(t, {
                        desc = vo.desc
                    })
                end
            end
        end
    elseif self.curLevelType == Constants.IDType.QuestAdvancedTraining then    --高端副本
        t = {}
        table.insert(t, QuestConfMgr:GetInstance():GetQuestConditionWithMoreCf(self.curLevelVo.conditionId, self.curLevelVo.conditionValue))
    else
        local _
        _, t = QuestConfMgr:GetInstance():GetQuestConditions(self.curLevelId, nil, self._conditionParas)
    end 
    return t
end

--获取爬塔的buff
function UIFightTeamDialog:GetTowerBuffData()
    local t = {}
    local allLineVo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.curLevelId)
    if allLineVo then
        for i = 1, table.count(allLineVo) do
        --只有一个
            local vo = allLineVo[i]
            if vo then
                local skillId = checkNumber(vo.halo)
                if skillId > 0 then
                    local vo = CardConfMgr:GetInstance():GetSkillByRefId(skillId, 1)
                    if vo then
                        for i = 1, 7 do
                            local buffId = checkNumber(vo:Get("effect"..i))
                            if buffId > 0 then
                                table.insert(t, {
                                    buffId = buffId, 
                                    targetId = checkNumber(vo:Get("effectTarget"..i))  --101自己， 102 敌方
                                 })
                            end
                        end  
                        local buffId = checkNumber(vo:Get("damageEffect"))
                        if buffId then
                            table.insert(t, {
                                buffId = buffId, 
                                targetId = checkNumber(vo:Get("damageTarget"))  --101自己， 102 敌方
                             })
                        end
                    end
                end
            end
        end
    end
    return t
end

