--获取奖励数据
function UIFightTeamDialog:GetRewardDatas()
    local t
    if self.curLevelType == Constants.IDType.QuestGachaCoin or self.curLevelType == Constants.IDType.QuestGachaCoinChallenge then
        t = {}
        local perRewards = CfUtils.Split(self.curLevelVo.perReward)
        if perRewards then
            for i = 1, #perRewards do
                table.insert(t, {
                    id = perRewards[i],
                    num = nil
                })
            end 
        end
    elseif self.curLevelType == Constants.IDType.QuestMaze then
        t = {}
        local MazeMgr = import('Game.Maze.MazeMgr'):GetInstance()
        local data = MazeMgr:GetCurrentChooseInfo()
        local difficultyVo = CfUtils.GetCfVo(AutoIds.IdSetting366, "PatrolDifficultyCoefficientVo", MazeMgr.mazeDifficultyId)
        local questRewardId
        if checkNumber(data.type) == 1 then
            questRewardId = difficultyVo.lowRewardId
        elseif checkNumber(data.type) == 2 then
            questRewardId = difficultyVo.midRewardId
        elseif checkNumber(data.type) == 3 then
            questRewardId = difficultyVo.bossRewardId
        end
        if questRewardId == -1 then
            questRewardId = CfUtils.GetCfVo(AutoIds.IdSetting367, "PatrolFloorRewardsVo", checkString(MazeMgr.mazeDifficultyId)..checkString(MazeMgr.currentFloor)).rewardId
        end
        local rewardVo = CfUtils.GetCfVo(AutoIds.IdSetting752, "QuestRewardVo", questRewardId)
        local items = CfUtils.Split(rewardVo.showItem)
        local showItemTags = CfUtils.Split(rewardVo.showItemTag)
        local showItemNums = CfUtils.Split(rewardVo.showItemNum)
        if items and showItemTags and showItemNums then
            for i = 1, #items do
                local reward = {
                    ["id"] = checkNumber(items[i]),
                    ["num"] = checkNumber(showItemNums[i]),
                    ["type"] = checkNumber(showItemTags[i]),
                }
                table.insert(t, reward)
            end
        end
    else
        local rewardData = RewardConfMgr:GetTeamShowRewardData(self.curLevelId)
        if not rewardData then
            return nil
        end

        t = {}
        local count = 0
        --领取过的不显示
        for k, v in pairs(rewardData) do
            if v.type == Constants.TeamShowRewardType.StarType then
                if not QuestConfMgr:GetInstance():IsPassAndCompleteAllCdtQuest(self.curLevelId) then
                    table.insert(t, v)
                    count = count + 1
                end
            elseif v.type == Constants.TeamShowRewardType.FristType then
                --高级装备副本
                if self.curLevelType == Constants.IDType.QuestSeniorEquipCopy then
                    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
                    if not equipQuestComp:IsPassQuestById(equipQuestComp:GetCurSeniorQuestId()) then
                        table.insert(t, v)
                        count = count + 1
                    end
                else
                    if not QuestConfMgr:GetInstance():IsPassQuest(self.curLevelId) then
                        table.insert(t, v)
                        count = count + 1
                    end
                end
            else
                table.insert(t, v)
                count = count + 1
            end
            if count >= 3 then
                return t
            end
        end
    end
    return t
end

