function UIFightTeamDialog:FillMainQuestRecommandBtn()
    if isNull(self.BtnRecommendLineupRoot) then return end

    local isMainQuest = self.curLevelType == Constants.IDType.QuestMain or self.curLevelType == Constants.IDType.QuestMainChallenge
    if not isMainQuest then
        KTool.SetActive(self.BtnRecommendLineupRoot, false)
