function UIFightTeamDialog:FillBtnRewardTimes()
    CfUtils.SetActive(self.TextNumOfTime.gameObject,false)
    if self.curLevelType == Constants.IDType.QuestMainChallenge then
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)
        if not isNull(vo) and (checkNumber(vo.monsteType) == Constants.RoleClass.Boss) then
            CfUtils.SetActive(self.TextNumOfTime.gameObject,true)
            ---@type QuestComponent
            local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
            local totalRewardTime = comp:GetChallengeTotalTimes()
            local havePassTime = comp:GetChallengePassedTimes()
            local leaveTime = totalRewardTime - havePassTime
            CfUtils.FillText(self.TextNumOfTime,localize("剩余奖励次数：_num_",{_num_ = string.format("<color=#FF69CE>%s</color>",leaveTime)}))
        end
    end
end

function UIFightTeamDialog:FillPowerInfo(teams)
    if self.curLevelType == Constants.IDType.QuestTalent then  --天赋
        --KTool.SetActive(self.TextLowPower, false)
        CfUtils.FillText(self.FightPower, "----")
    elseif self.curLevelId == Constants.SpecialQuestId.LadderStruggleId
    or self.curLevelId == Constants.SpecialQuestId.LadderStruggleSingleId 
    or self.curLevelId == Constants.SpecialQuestId.ClubGVGId
    or self.curLevelId == Constants.SpecialQuestId.FriendPVPId then
        CfUtils.FillText(self.FightPower, self._power)
    elseif self.curLevelType == Constants.IDType.QuestNightCatTower or self.curLevelType == Constants.IDType.QuestNightCatBoss then
        ---@type NightCatQuestComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NightCatQuestComponent)
        local buffAddPower = comp:GetEquipBuffAddPower()
        CfUtils.SetActive(self.BtnExplain, true)
        CfUtils.SetUISwitchText(self.FightPower, 1)
        CfUtils.FillText(self.FightPower, self._power + buffAddPower)
    elseif self.curLevelType == Constants.IDType.MournTower or self.curLevelType == Constants.IDType.MournBoss then
        ---@type ActivityMournUtils
        local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')
        local buffAddPower = ActivityMournUtils.GetEquipBuffAddPower()
        CfUtils.SetActive(self.BtnExplain, true)
        CfUtils.SetUISwitchText(self.FightPower, 1)
        CfUtils.FillText(self.FightPower, self._power + buffAddPower)
    else
        local power = self._power
        local isLowPower = (power < checkNumber(self.curLevelVo.proposalLevel))
        --KTool.SetActive(self.TextLowPower, isLowPower)
        --超过推荐战斗力
        --if not isLowPower then
        --    local text = self.FightPower.transform:GetComponent(typeof(TextMeshProUGUI))
        --    text.color = Color.New(1, 1, 1, 1)
        --end
        CfUtils.SetUISwitchText(self.FightPower, isLowPower and 2 or 1)
        CfUtils.FillText(self.FightPower, self._power)
    end
end

