--绘制队伍
function UIFightTeamDialog:FillTeamMembers(teams, isDontShowAni)
    self:FillBtnFight()
    
    if not teams then return end
    self.teamTab = teams

    self._allTeamPosInfoGo = {}
    self._power = 0
    local count = teamComponent:GetMaxSelectNumByQuestId(self.curLevelId)
    count = math.max(4, count)
    -- local catId = teamComponent:GetCurSkillCompoundId(self.curLevelId, self._teamIndex)
    -- ---@type CatEggDojo
    -- local catBallData
    -- if checkNumber(catId) > 0 then
    --     catBallData = catEggComponent:GetCat(catId)
    -- end

    --- 计算战力需要星级 这里设置下
    ---@type TeamCatBallDojo[]
    local teamCats
    if self._isShowCatBall then
        teamCats = teamComponent:GetTeamCatByQuestId(self.curLevelId, self._teamIndex)
       for index, value in ipairs(teamCats) do
           if checkNumber(value.playerCatId) > 0 then
               ---@type CatEggDojo
               local catEggDojo = catEggComponent:GetCatById(value.playerCatId)
               value:SetStar(catEggDojo.star)
           end
       end
    end

    local emotionBonusDict = {}
    local moduleId = Constants.GuideModule.EmotionBonus
    ---@type GuideUtils
    local GuideUtils = import('Game.UI.Guide.GuideUtils')
    local guideComplete = GuideUtils.CheckIsCompleteGuideByModuleId(moduleId)
    if guideComplete then
        -- 计算共鸣的情绪 id列表
        emotionBonusDict = CardUtils.CalculateEmotionBonusDict(teams)
    end

    for i = 1, count do
        local teamGo = self["TeamNode"..i]
        CfUtils.SetActive(teamGo, true)
        local showEmotionBonus = CardUtils.ConsumeEmotionBonusDict(teams[i], emotionBonusDict)
        self:FillTeamMember(teamGo, teams[i], i, teamCats, isDontShowAni, showEmotionBonus)
    end

    for i = 1, count do
        local teamGo = self["TeamNode"..i]
        ---@type UIFightTeamTeamNode
        local scr = CfUtils.GetLuaScr(teamGo, UIFightTeamTeamNode)
        if scr then
            local cardData, isLockHelper = self:GetCardData(teams[i])
            if not isLockHelper then
                scr:InitChangePosInfo(self._allTeamPosInfoGo, function()
                end, self.curLevelId, self._teamIndex)
            end
        end
    end
end

--绘制队伍队员
function UIFightTeamDialog:FillTeamMember(go, tmDojo, index, teamCats, isDontShowAni, showEmotionBonus)
    if self.curLevelType == Constants.IDType.ActivityCrisis then
        if isNull(tmDojo) and (index > self._maxTeamMember) then
            --该位置是否被限制上阵
            local isLimitPos = (index > self._maxTeamMember)
            ---@type UIFightTeamTeamNode
            local scr = CfUtils.GetLuaScr(go, UIFightTeamTeamNode)
            scr:FillLimitStatus(isLimitPos)
            return
        end
    end

    if isNull( go) or not tmDojo then
        return
    end
    ---@type UIFightTeamTeamNode
    local scr = CfUtils.GetLuaScr(go, UIFightTeamTeamNode)
    if scr then
        --该位置是否被限制上阵
        local isLimitPos = (index > self._maxTeamMember)
        scr:FillLimitStatus(isLimitPos)
        if self._isHideFetters then
            scr:FillFetterStatus(false)
        end

        table.insert(self._allTeamPosInfoGo, {
            memberPos = index,
            go = go,
            pos = go.transform.localPosition,
            isLimitPos = isLimitPos or (checkNumber(tmDojo.refId) == 0)
        })

        if not isLimitPos then
            ---@type CardDojo
            local cardData, isLockHelper = self:GetCardData(tmDojo)
            scr:Refresh(cardData, function()
                if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
                    if not self._isOwn then
                        return
                    end
                end

                if not isLockHelper then
                    UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {levelId = self.curLevelId, activityUuid = self._activityUuid, upBuffData = self._upBuffData, teamIndex = self._teamIndex, patrolMaze = self._patrolMaze}}, {
                        { id = Constants.UITypeIds.UIFightTeamChoose}
                    })
                else
                    GameUtils.Toast(localize("该武装已锁定，不可变更。"))
                end
            end, function()
                if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
                    if not self._isOwn then
                        return
                    end
                end

                --还有多余的牌
                if self:IsEnterTeamCardChoose() then
                    UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {levelId = self.curLevelId, activityUuid = self._activityUuid, upBuffData = self._upBuffData, teamIndex = self._teamIndex, patrolMaze = self._patrolMaze}}, {
                        { id = Constants.UITypeIds.UIFightTeamChoose}
                    })
                else
                    GameUtils.Toast(localize("武装不足"))
                end
            end, index, self.curLevelId, self.teamTab,self._teamIndex)

            --羁绊
            scr:FillFettersInfo(tmDojo, function()
                if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
                    if not self._isOwn then
                        return
                    end
                end

                if checkNumber(tmDojo.cardId) <= 0 then
                    GameUtils.Toast(localize("需要先上阵卡牌"))
                    return
                end
                if not isLockHelper then
                    UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamCardChoose, parameters = {targetCardId = tmDojo.cardId, chooseCardStatu = Constants.ChooseCardStatus.Fetter, levelId = self.curLevelId, activityUuid = self._activityUuid, upBuffData = self._upBuffData, teamIndex = self._teamIndex}}, {
                        { id = Constants.UITypeIds.UIFightTeamChoose}
                    })
                --else
                    --GameUtils.Toast(localize("该武装已锁定，不可变更。"))
                end
            end, isDontShowAni)

            --scr:FillLockStatus(isLockHelper)
            if isLockHelper then
                scr:FillCardHelper()
            end
            if self._upBuffData then
                scr:FillUpBuffInfo(self._upBuffData)
            end

            if cardData then
                if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) and not self._isOwn then
                    self._power = self._power + checkNumber(cardData.combatValue)
                elseif self.curLevelType == Constants.IDType.QuestPatrolMaze then 
                    local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
                    local patrolMazeComp  = PatrolMazeUtils.GetComp()
                    ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
                    local areaDojo = self._patrolMaze.areaDojo
                    local mazeCardDojo = areaDojo:GetMazeCard(cardData.id)
                    cardData = mazeCardDojo:GetCardDojo()

                    ---@type CardProgressionUtils
                    local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
                    local entity = CardProgressionUtils.GenerateEntityByRobot(cardData)
                    entity:FillPureCard(true)
                    if mazeCardDojo.isAssist then
                        local assistVo = PatrolMazeUtils.GetAssistCardVo(mazeCardDojo.assistId)
                        entity:FillAdditionMap(assistVo.additionMap)
                    end
                    self._power = self._power + FormulaUtils.CalcCardCombatEffectiveness(entity, nil, nil)
                elseif self.curLevelType == Constants.IDType.Fairyland then
                    cardData = clone(cardData)
                    for i = 1, 6 do
                        cardData["equipment" .. tostring(i)] = 0
                    end
                    ---@type CardProgressionUtils
                    local CardProgressionUtils = import("Game.CardProgression.CardProgressionUtils")
                    local entity = CardProgressionUtils.GenerateEntityByRobot(cardData)
                    entity.isIgnoreGlobal = true

                    local synergiesId, synergiesDojo
                    if checkNumber(tmDojo.fettersId) > 0 then
                        local dojo = cardComponent:GetCardById(tmDojo.fettersId)
                        synergiesId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(cardData.cardId, dojo.cardId)
                        synergiesDojo = dojo
                    end

                    self._power = self._power + FormulaUtils.CalcCardCombatEffectiveness(entity, {synergiesId = synergiesId, synergiesDojo = synergiesDojo, teamCats = teamCats}, nil)
                else
                    if isLockHelper then
                        local power = FormulaUtils.GetCardFightingStrengthen(cardData, {teamCats = teamCats}, isLockHelper)
                        self._power = self._power + power
                    else
                        local synergiesId, synergiesDojo
                        --local addAttrs = {}
                        if checkNumber(tmDojo.fettersId) > 0 then
                            local dojo = cardComponent:GetCardById(tmDojo.fettersId)
                            synergiesDojo = dojo
                            synergiesId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(cardData.cardId, dojo.cardId)
                            --addAttrs = CardConfMgr:GetInstance():GetFettersAddAttr(cardData, dojo)
                        end
                        -- local catBallId, catBallStar
                        -- if teamCats and checkNumber(catBallData.cafeEnergy) > 0 then
                        --     catBallId, catBallStar = catBallData.catId, catBallData.star
                        -- end
                        self._power = self._power + FormulaUtils.GetCardFightingStrengthen(cardData, 
                                {
                                    synergiesId = synergiesId, 
                                    synergiesDojo = synergiesDojo, 
                                    teamCats = teamCats, 
                                }, 
                                isLockHelper)

                                --print(self._power)
                    end
                end

                local hpEnergyData 
                if self.curLevelType == Constants.IDType.QuestMaze then
                    hpEnergyData = cardData
                --elseif self.curLevelType == Constants.IDType.QuestSeniorEquipCopy then
                --    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
                --    --hpEnergyData = equipQuestComp:GetEquipCopyCardHpEngyData(tmDojo.refId)
                --    scr:FillXieLiZhi()
                elseif self.curLevelType == Constants.IDType.QuestPatrolMaze then 
                    ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
                    local areaDojo = self._patrolMaze.areaDojo
                    local mazeCardDojo = areaDojo:GetMazeCard(cardData.id)
                    hpEnergyData = {
                        hpPercent = mazeCardDojo.hpPercent,
                        energy    = mazeCardDojo.energy,
                    }
                elseif self.curLevelType == Constants.IDType.QuestTalent then 
                    local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
                    hpEnergyData = talentQuestComponent:GetCardHpEngyData(tmDojo.refId)
                end
                if hpEnergyData then 
                    local maxEnergyNum = 0
                    if self.curLevelType == Constants.IDType.QuestPatrolMaze then 
                        maxEnergyNum = 0
                    else
                        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(cardData.cardId)
                        if cardVo then
                            maxEnergyNum = checkNumber(cardVo.maxSp)
                        end
                    end
                    scr:FillHpEnergy(hpEnergyData, maxEnergyNum)
                end
                
                -- 情绪共鸣
                scr:SetEmotionBonusLoopFX(showEmotionBonus)
                if showEmotionBonus and (not isDontShowAni) then
                    scr:ShowEmotionBonusFlyFX(self.FightTeamBonusNode.gameObject)
                else
                    scr:CloseEmotionBonusFlyFX()
                end
            end
        end
    end
end

--队伍队员数据转卡牌数据
---@param tmDojo TeamMemberDojo
function UIFightTeamDialog:GetCardData(tmDojo)
    if not tmDojo then
        return nil, false
    end

    if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) and not self._isOwn then
        return tmDojo.cardInfo, false
    end

    local isLockHelper = false
    ---@type CardDojo
    local cardData = nil
    local type = checkNumber(tmDojo.type)
    if type == Constants.TeamMemberType.None then
        return nil, isLockHelper
    elseif type == Constants.TeamMemberType.PlayerCard then
        if self.curLevelType == Constants.IDType.QuestMaze then
            ---@type MazeTeamComponent
            local mazeTeamComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeTeamComponent, Constants.MazeTeamEntityId)
            cardData = mazeTeamComp:GetFakeRoleData(tmDojo.refId)
        else
            cardData = cardComponent:GetCardById(tmDojo.refId)
        end
    elseif type == Constants.TeamMemberType.PlayerCardWithoutEquip then
        cardData = clone(cardComponent:GetCardById(tmDojo.refId))
        for i = 1, 6 do
            cardData["equipment" .. tostring(i)] = 0
        end
    elseif type == Constants.TeamMemberType.HelperCard then
        if self.curLevelType == Constants.IDType.QuestMaze then
            ---@type MazeTeamComponent
            local mazeTeamComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MazeTeamComponent, Constants.MazeTeamEntityId)
            cardData = mazeTeamComp:GetFakeRoleData(tmDojo.refId)
        end
    elseif type == Constants.TeamMemberType.PatrolMazeCard then
        if self.curLevelType == Constants.IDType.QuestPatrolMaze then
            local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
            local patrolMazeComp  = PatrolMazeUtils.GetComp()
            local mazeAreaDojo    = patrolMazeComp:GetHomeDojo():GetAreaDojo(tmDojo.areaId)
            cardData = mazeAreaDojo:GetMazeCard(tmDojo.refId):GetCardDojo()
        end
    elseif type == Constants.TeamMemberType.QuestLockHelperCard then
        isLockHelper = true
        --获取机器人数据
        cardData = BattleHelperConfMgr:GetInstance():GetMainLevelHelper(self.curLevelVo.petLineup, tmDojo.refId)
    end
    return cardData, isLockHelper
end

