function UIFightTeamDialog:FillEntrustInfo()
    local appointment = checkNumber(self.curLevelVo.appointment)
    --不开放的直接隐藏
    if appointment == Constants.EntrustBattleOpenCondition.NotOpen then 
        KTool.SetActive(self.BtnEntrustReady, false)
    else
        --KTool.SetActive(self.BtnEntrustReady, true)
        --是否未解锁
        local isUnLock = QuestConfMgr:GetInstance():IsUnlockEntrust(self.curLevelId)
        KTool.SetActive(self.Lock, not isUnLock)
        CfUtils.FillImage(self.Imgico, 'uiatlas/common/common_ico_lock_1.png')
    end
end

--显示体力
function UIFightTeamDialog:FillStrengthNode()
    --主线重复刷得不要体力
    if QuestConfMgr:GetInstance():IsRepeatQuest(self.curLevelId) then
        KTool.SetActive(self.CommonBtnConsumePop, false)
        return
    end

    --试炼不显示体力
    if self.curLevelType == Constants.IDType.QuestTrail
    or self.curLevelId == Constants.SpecialQuestId.LadderStruggleId
    or self.curLevelId == Constants.SpecialQuestId.LadderStruggleSingleId
    or self.curLevelId == Constants.SpecialQuestId.ClubGVGId
    or self.curLevelType == Constants.IDType.Fairyland
    or self.curLevelId == Constants.SpecialQuestId.FriendPVPId then
        KTool.SetActive(self.CommonBtnConsumePop, false)
    else
        CfUtils.FillImage(self.ImageIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(self.curLevelVo.costItem))
        local times = 1
        if self.curLevelType == Constants.IDType.ActivityWorldMiniQuestBoss then
            times = checkInt(KCookie.Get("MINI_BOSS_CONSUME"))
            if times == 0 then
                times = 1
            end
        elseif self.curLevelType == Constants.IDType.ActivityCakeBoss or self.curLevelType == Constants.IDType.QuestMidFestivalBoss then
            times = checkInt(KCookie.Get(string.format("COMMON_BOSS_CONSUME_%s",self._activityUuid)))
            times = (times == 0) and 1 or times
        end
        local costNum = (checkNumber(self.curLevelVo.costNum) + checkNumber(self.curLevelVo.costNumLose)) * times --策划要求修改为只读costNum
        if self.curLevelType == Constants.IDType.QuestCoinsCopy
                or self.curLevelType == Constants.IDType.QuestExpCopy
                or self.curLevelType == Constants.IDType.QuestUpStarCopy
                or self.curLevelType == Constants.IDType.QuestSeniorEquipCopy
                or self.curLevelType == Constants.IDType.QuestMediumPT
                or self.curLevelType == Constants.IDType.QuestBambooChanllenge
                or self.curLevelType == Constants.IDType.QuestHalloween
                or self.curLevelType == Constants.IDType.QuestDaily
                or self.curLevelType == Constants.IDType.QuestMapDecryptionTracking
                or self.curLevelType == Constants.IDType.QuestMapDecryptionMap 
        then
            if self.isThreeTripleMode then
                costNum = costNum * (3 - self.freeTimesRemain)
            else
                if self.freeTimesRemain > 0 then
                    costNum = 0
                end
            end
        end
        if costNum ~= 0 then
            -- 计算天赋加成
            costNum = GameUtils.CalculateCostNumWithTalentAddition(self.curLevelVo, costNum)

            --local cor = ((GoodsUtils.GetThingNo(self.curLevelVo.costItem) >= costNum) and Color.New(211/255, 211/255, 211/255, 255/255) or Color.New(255/255, 0/255, 0/255, 255/255))
            --CfUtils.SetColor(self.StrengthNum, cor)
            --CfUtils.FillText(self.StrengthNum, "x"..costNum)
            CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, self.curLevelVo.costItem, costNum, false, 1, {questId = self.curLevelId})
            KTool.SetActive(self.CommonBtnConsumePop, true)
        else
            KTool.SetActive(self.CommonBtnConsumePop, false)
        end
    end
end

--- 扫荡
function UIFightTeamDialog:FillSweepBtnGroup()
    local canSweep = self.curLevelType == Constants.IDType.QuestDaily or self.curLevelType == Constants.IDType.QuestRegion
