    --                 GameUtils.SecondConfirm(localize("当前猫球能量值不足，光环技无法生效，是否进入战斗？"), function()
    --                     if checkNumber(self._power) < checkNumber(self.curLevelVo.proposalLevel) then
    --                         GameUtils.SecondConfirm(localize("当前战力低于推荐战力，是否继续挑战？"), function()
    --                             self:ToEnterFight(isContinuous)
    --                         end)
    --                     else
    --                         self:ToEnterFight(isContinuous)
    --                     end
    --                 end, function()
                        
    --                 end)
