    -- end
    if self.curLevelType == Constants.IDType.QuestNightCatTower or self.curLevelType == Constants.IDType.QuestNightCatBoss or self.curLevelType == Constants.IDType.Fairyland
            or self.curLevelType == Constants.IDType.MournTower or self.curLevelType == Constants.IDType.MournBoss  then
