--开始战斗
function UIFightTeamDialog:ToEnterFight(isContinuous)
    local t = teamComponent:GetTeamByQuestId(self.curLevelId, self._teamIndex)
    if not t then
        return
    end

    local args = {}
    if self.curLevelType == Constants.IDType.QuestBambooChanllenge then   --竹林挑战副本
        args = {activityUuid = self._activityUuid, isThreeTripleMode = self.isThreeTripleMode and 1 or 0}
    elseif self.curLevelType == Constants.IDType.QuestCoinsCopy
            or self.curLevelType == Constants.IDType.QuestExpCopy
            or self.curLevelType == Constants.IDType.QuestUpStarCopy
            or self.curLevelType == Constants.IDType.QuestSeniorEquipCopy
            or self.curLevelType == Constants.IDType.QuestDaily
    then
        args = {isThreeTripleMode = self.isThreeTripleMode and 1 or 0}
        KCookie.Set("isOpenTripleMode", self.isThreeTripleMode)
        if self.curLevelType == Constants.IDType.QuestCoinsCopy then
            KCookie.Set("DailyQuest"..Constants.IDType.QuestCoinsCopyType, self.curLevelId)
        elseif self.curLevelType == Constants.IDType.QuestExpCopy then
            KCookie.Set("DailyQuest"..Constants.IDType.QuestExpCopyType, self.curLevelId)
        elseif self.curLevelType == Constants.IDType.QuestUpStarCopy then
            KCookie.Set("DailyQuest"..Constants.IDType.QuestUpStarCopyType, self.curLevelId)
        end
    elseif self.curLevelType == Constants.IDType.QuestMediumPT then
        KCookie.Set("MediumPTQuest", self.curLevelId)
        args = {isThreeTripleMode = self.isThreeTripleMode and 1 or 0, activityUuid = self._activityUuid}
    elseif self.curLevelType == Constants.IDType.QuestDirectionalFight then
        args = {activityUuid = self._activityUuid}
    elseif self.curLevelType == Constants.IDType.QuestCardExperience or self.curLevelType == Constants.IDType.ActivityQuestSkinExperience then
        args = {activityUuid = self._activityUuid}
    elseif self.curLevelType == Constants.IDType.QuestAdvancedTraining then
        KCookie.Set("AdvancedTrainingQuest", self.curLevelId)
    elseif self.curLevelType == Constants.IDType.QuestBossChallenge then
        args = {activityUuid = self._activityUuid, scheduleId = self._scheduleId}
    elseif self.curLevelType == Constants.IDType.QuestNightCatTower or self.curLevelType == Constants.IDType.QuestNightCatBoss then
        args = {activityUuid = self._activityUuid}
    elseif self.curLevelType == Constants.IDType.MournPlot or self.curLevelType == Constants.IDType.MournBoss or self.curLevelType == Constants.IDType.MournTower then
        args = {activityUuid = self._activityUuid}
    elseif self.curLevelType == Constants.IDType.QuestHalloween then
        args = {activityUuid = self._activityUuid, isThreeTripleMode = self.isThreeTripleMode and 1 or 0}
    elseif self.curLevelType == Constants.IDType.QuestMapDecryptionTracking or self.curLevelType == Constants.IDType.QuestMapDecryptionMap then
        args = {activityUuid = self._activityUuid, isThreeTripleMode = self.isThreeTripleMode and 1 or 0, isDisableRecoveryBgm = true}
    elseif self.curLevelType == Constants.IDType.QuestMidFestivalStory or self.curLevelType == Constants.IDType.QuestMidFestivalRecord or self.curLevelType == Constants.IDType.QuestMidFestivalBoss then
        args = { activityUuid = self._activityUuid }
    elseif self.curLevelType == Constants.IDType.DreamAdventuresPlot then
        args = { activityUuid = self._activityUuid }
    elseif self.curLevelType == Constants.IDType.ActivityWorldMiniQuestBoss then
        args = { activityUuid = self._activityUuid }
    elseif self.curLevelType == Constants.IDType.ActivityWorldMiniQuest then
        args = { activityUuid = self._activityUuid }
    elseif self.curLevelType == Constants.IDType.DreamAdventuresLuby then
        args = { activityUuid = self._activityUuid, eventId = self._eventId }
    elseif self.curLevelType == Constants.IDType.JapaneseStoryBoss then
        args = { activityUuid = self._activityUuid }
    elseif self.curLevelType == Constants.IDType.CustomTrain then
        args = { activityUuid = self._activityUuid }
    elseif self.curLevelType == Constants.IDType.JapaneseStoryPlot then
        args = { activityUuid = self._activityUuid }
    elseif self.curLevelType == Constants.IDType.QuestPatrolMaze then
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local areaDojo = self._patrolMaze.areaDojo
        ---@type PatrolMazeFloorPathDojo @ 当前所在路径dojo
        local pathDojo = self._patrolMaze.pathDojo
        ---@type PatrolMazeFloorLevelDojo @ 当前所在层级dojo
        local levelDojo = self._patrolMaze.levelDojo
        args = { areaId = areaDojo.areaId, floor = pathDojo.floorNum, level = levelDojo.floorLevel, questId = levelDojo.typeRefId }
    end

    args.routerType = self._routerType

    teamComponent:SetTeamReq(self.curLevelId, function()
        local isActive = CookingUtils.IsActiveBattleFood()
        -- cookingComponent:CookingBattleCookingSwitchReq(isActive and 1 or 0, function()
            if self.curLevelType == Constants.IDType.QuestMaze then
                local MazeMgr = import('Game.Maze.MazeMgr'):GetInstance()
                MazeMgr.isPassedBefore = MazeMgr.isPassed
                local pages = UIModule.Instance.uiPages
                if pages.Count > 2 then
                    local jumpLastId = KCookie.Get(Constants.UICacheDataKeys.JumpLastModuleId)
                    if isNull(jumpLastId) then
                        UIModule.RemoveRecordToCustomDialog(Constants.UITypeIds.ActionEntryDialog)
                    else
                        UIModule.RemoveRecordToCustomDialog(jumpLastId)
                        KCookie.Set(Constants.UICacheDataKeys.JumpLastModuleId)
                    end
                end

            end

            if self.curLevelType == Constants.IDType.QuestRegion or self.curLevelType == Constants.IDType.QuestDaily then
                RegionQuestMgr:GetInstance():ClearCurMapGo()
                KCookie.Set("LastEntryBattleQuestId", self.curLevelId)
            end
            
            self.controller:SetBackArgument(true)
            fightPreWarMgr:FightEnter(self.curLevelId, args)

            if isContinuous then
                QuestConfMgr:GetInstance():SetContinuousBattle(true)
            else
                QuestConfMgr:GetInstance():SetContinuousBattle(false)
            end
        -- end)
    end)
end

function UIFightTeamDialog:SaveAndBackToLadderStuggleFormationPanel()
    local t = teamComponent:GetTeamByQuestId(self.curLevelId, self._teamIndex)
    if not t then
        UIModule.BackDialog()
        return
    end
    teamComponent:SetTeamReq(self.curLevelId, function()
        UIModule.BackDialog()
    end)
end

function UIFightTeamDialog:SaveChaoticRecallTeam()
    ---@type ChaoticRecallMgr
    local ChaoticRecallMgr = import('Game.UI.FightReady.ChaoticRecall.ChaoticRecallMgr')
    local teamsInfo = ChaoticRecallMgr:GetInstance():GetTeamInfoByQuestId(self.curLevelId) or {}
    local questVo = CfUtils.GetCfVo(AutoIds.IdSetting6108,"ChaoticRecallLevelVo",self.curLevelId)
    local t = clone(teamsInfo)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3007)
    for i, v in ipairs(t) do
        v.cardsInfo = teamComponent:GetAllCardId(v.cardsInfo, true)
        if isUnlock then
            v.catsInfo  = teamComponent:GetAllCatId(v.catsInfo, true)
        else
            v.catsInfo  = nil
        end
    end

    GameUtils.Request(Interfaces.OverseaNightmareSetTeam,{cardIds = table.serialize(t) , nodeId = questVo.nodeId },function(request,response)
        if checkNumber(response.errCode) == 0 then
            UIModule.BackDialog()
        end
    end)
end

