--是否可以战斗
function UIFightTeamDialog:IsCanBattle()
    local t = teamComponent:GetTeamByQuestId(self.curLevelId, self._teamIndex)
    if not t then
        return false, localize("队伍不能为空")
    end
    local count = teamComponent:GetTeamMemberCount(t) 
    if count < 1 then
        return false, localize("队伍不能为空")
    end

    --主线复刷不判断体力
    if not QuestConfMgr:GetInstance():IsRepeatQuest(self.curLevelId) and self.curLevelType ~= Constants.IDType.Fairyland then
        local needNum = (checkNumber(self.curLevelVo.costNum) + checkNumber(self.curLevelVo.costNumLose))
        if self.curLevelType == Constants.IDType.QuestCoinsCopy or self.curLevelType == Constants.IDType.QuestExpCopy or self.curLevelType == Constants.IDType.QuestUpStarCopy or self.curLevelType == Constants.IDType.QuestSeniorEquipCopy 
         or self.curLevelType == Constants.IDType.QuestBambooChanllenge or self.curLevelType == Constants.IDType.QuestMediumPT or self.curLevelType == Constants.IDType.QuestHalloween or self.curLevelType == Constants.IDType.QuestDaily then
            if self.isThreeTripleMode then
                needNum = needNum * (3 - self.freeTimesRemain)
            else
                if self.freeTimesRemain > 0 then
                    needNum = 0
                end
            end
        end
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)
        if vo then
            if checkNumber(vo.levelType) == Constants.RegionSecondQuestType.Equip then
                ---装备本
                --@type PlayerComponent
                local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                local status = checkNumber(playerComponent.playerDojo.consumeCopyActivity.status)
                local times = checkNumber(playerComponent.playerDojo.consumeCopyActivity.residueNum)
                if status == 1 and times > 0  then
                    ---@type TableML.TableFile
                    local tableFile = settingModule.Get(AutoIds.IdSetting313)
                    ---@type TableML.TableFileRow
                    local row = tableFile:GetByPrimaryKey(checkNumber(self.curLevelId), false)
                    if row then
                        needNum = checkNumber(row:Get("costNum")) + checkNumber(vo.costNumLose)
                    end
                end
            end
        end
        -- 计算天赋加成
        needNum = GameUtils.CalculateCostNumWithTalentAddition(self.curLevelVo, needNum)
        --体力
        local costNum = GoodsUtils.GetThingNo(self.curLevelVo.costItem)
        if checkNumber(self.curLevelVo.costItem) == ActionUtils.GetDailyQuestTicketId() then
            costNum = ActionUtils.GetDailyQuestCurTicketAddNum()
        end
        if costNum < needNum then
            --体力是门票
            if checkNumber(self.curLevelVo.costItem) == Constants.Currency.HpId then
                UIModule.OpenDialog({id = Constants.UITypeIds.UIHPDialog, parameters = { overrideSorting = 1050 } })
                return false, 1
            elseif checkNumber(self.curLevelVo.costItem) == 3000021 then
                UIModule.OpenDialog({id = Constants.UITypeIds.StoreDiamondExchangeDialog, parameters = {id = 5100021}})
                return false, 1
            else
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.curLevelVo.costItem)
                if checkNumber(self.curLevelVo.costItem) == 900302 then
                    return false, localize("_name_不足，请前往「集章兑换」获得", {_name_ = goodsVo.name})
                else
                    return false, localize("_name_不足", {_name_ = goodsVo.name})
                end
            end
        end
    end

    if not self.isContentCondition then
        return false, localize("未满足队伍条件")
    end

    if self.curLevelType == Constants.IDType.QuestHalloween then
        local HalloweenUtils = import('Game.UI.FightReady.UIJackpotDungoen.HalloweenUtils')
        local isOpen = HalloweenUtils.IsOpen()
        if not isOpen then
            return false, localize("活动已关闭")
        end
    end

    local isCanSet = QuestConfMgr:GetInstance():IsTeamCanSet(t, self.curLevelId)
    if not isCanSet then
        return false, localize("不符合上阵条件")
    end

    -- local isFilled, packetVo = GoodsUtils.IsPacketFilled()
    -- if isFilled then
    --     return false, localize("_name_背包已满，请前往清理", {_name_ = packetVo.name})
    -- end
    return true
end

--是否还有足够的队员上阵
function UIFightTeamDialog:IsEnterTeamCardChoose()
    local cards = self:GetAllCardsData()
    if not cards then
        return false
    end

    for i, v in ipairs(cards) do
        if not teamComponent:IsCardInTeam(self.curLevelId, v.id, self._teamIndex) then
            return true
        end
    end
    return false
end

--绘制装备副本条件
function UIFightTeamDialog:FillEquipCopyConditions()
    CfUtils.FillText(self.titleName, localize("调查条件"))
    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
    local t = {
        [1] = {
            title = localize("助力点上限"),
            num = equipQuestComp:GetCurQuestCostNum()
        },
        [2] = {
            title = localize("已占用助力点"),
            num = teamComponent:GetCurTeamXielizhi(self.teamTab)
        }
    }
    --定死的俩个go。。。
    for i = 1, #t do
        local go = self.FastReliefCdt.transform:Find("ImgBG"..i)
        if go then
            CfUtils.FillText(go.transform:Find("Txt1"), t[i].title)
            CfUtils.FillText(go.transform:Find("Txt2"), t[i].num)
        end
    end
end

