--自动编队
function UIFightTeamDialog:AutoFormation()
    local restPositionNum = teamComponent:GetMaxSelectNum(self.curLevelId, Constants.ChooseCardStatus.Normal, self._teamIndex) --初始空位数量
    if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
        restPositionNum = self._maxTeamMember
    elseif self.curLevelType == Constants.IDType.ActivityCrisis then
        restPositionNum = self._maxTeamMember
    end

    -- 数量限制
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId) or {}
    if questVo.roleNun 
    and (checkInt(questVo.roleNun) < restPositionNum) then
        restPositionNum = checkInt(questVo.roleNun)
    end
    
    --按照规则筛选后的自动编队的数据
    local cardTab = {}

    --机器人队伍 
    local helperTeam = QuestConfMgr:GetInstance():GetQuestHelpers(self.curLevelId)
    if table.count(helperTeam) > 0 then
        for i, cardData in ipairs(helperTeam) do
            table.insert(cardTab, CfUtils.GetTeamMemberDojo{
                type = cardData.type,
                refId = cardData.refId,
                cardId = cardData.cardId,
            })
            restPositionNum = restPositionNum - 1
        end
    end

    if restPositionNum > 0 then
        if self.isFirstClick then --第一次点击时才与服务器通讯
            self.isFirstClick = true
            --取得所有卡牌
            local cards = self:GetAllCardsData()
            local t = CardUtils.SortCardBySortType(cards, Constants.SortType.CombatPower, true)


            local vo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)
            --有上阵必须角色先取出来
            if vo and checkNumber(vo.roleRestrictions) > 0 then  -- 角色限制
                for i = 1, table.count(t) do
                    if restPositionNum > 0 then
                        local cardData = t[i]
                        if QuestConfMgr:GetInstance():CheckCardByTeamLimitId(vo.roleRestrictions, Constants.TeamLimitType.Must, cardData.cardId) then
                            local isCanJoinTeam = self:IsCanJoinTeam(cardData, cardTab)
                            if isCanJoinTeam then
                                local helperTeam = QuestConfMgr:GetInstance():GetQuestHelpers(self.curLevelId)
                                if teamComponent:IsCanJoinTeam(cardTab, cardData) and teamComponent:IsCanJoinTeam(helperTeam, cardData) then
                                    --添加到编队中
                                    local refId = cardData.id
                                    local type = Constants.TeamMemberType.PlayerCard
                                    if checkNumber(cardData.isAssistant) == 1 then
                                        type = Constants.TeamMemberType.HelperCard
                                    elseif self.curLevelType == Constants.IDType.Fairyland then
                                        type = Constants.TeamMemberType.PlayerCardWithoutEquip
                                    end
                                    table.insert(cardTab, CfUtils.GetTeamMemberDojo{
                                        type = type,
                                        refId = refId,
                                        cardId = cardData.cardId
                                    })
                                    restPositionNum = restPositionNum - 1
                                    if restPositionNum <= 0 then
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end

            for i = 1, table.count(t) do
                if restPositionNum > 0 then
                    local cardData = t[i]
                    local isCanJoinTeam = self:IsCanJoinTeam(cardData, cardTab)
                    if isCanJoinTeam then
                        --机器人队伍  没有会是空
                        local helperTeam = QuestConfMgr:GetInstance():GetQuestHelpers(self.curLevelId)
                        --过滤掉不符合条件的数据
                        if teamComponent:IsCanJoinTeam(cardTab, cardData) and teamComponent:IsCanJoinTeam(helperTeam, cardData) then
                            --添加到编队中
                            local refId = cardData.id
                            local type = Constants.TeamMemberType.PlayerCard
                            if checkNumber(cardData.isAssistant) == 1 then
                                type = Constants.TeamMemberType.HelperCard
                            elseif self.curLevelType == Constants.IDType.Fairyland then
                                type = Constants.TeamMemberType.PlayerCardWithoutEquip
                            end
                            if self.curLevelType == Constants.IDType.QuestPatrolMaze then
                                ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
                                local areaDojo = self._patrolMaze.areaDojo
                                table.insert(cardTab, areaDojo:GetTeamMemberDojo(refId, cardData.cardId))
                            else
                                table.insert(cardTab, CfUtils.GetTeamMemberDojo{
                                    type = type,
                                    refId = refId,
                                    cardId = cardData.cardId
                                })
                            end
                            restPositionNum = restPositionNum - 1
                            if restPositionNum <= 0 then
                                break
                            end
                        end
                    end
                else
                    break
                end
            end

            -- 是否卡牌不足，要空白数据补位
            local maxNum = 4
            if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
                maxNum = self._maxTeamMember
            end
            if table.count(cardTab) < maxNum then
                for i = table.count(cardTab) + 1, maxNum do
                    table.insert(cardTab, {})
                end
            end

            -- 羁绊数据
            if self.curLevelType ~= Constants.IDType.Fairyland then
                local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id20001)
                if isUnlock and not self._isHideFetters then
                    --找羁绊位
                    for k, v in pairs(cardTab) do
                        --有了人的位置上羁绊
                        if checkNumber(v.cardId) > 0 then
                            v.fettersId, v.fettersCardId = self:GetTeamFettersCard(v.cardId, cardTab)
                        end
                    end
                else
                    for k, v in pairs(cardTab) do
                        v.fettersId, v.fettersCardId = 0, 0
                    end
                end
            end
            
            if AnnihilationUtils.QuestTypeIsAnnihilation(self.curLevelType) then
                local t1 = {
                    {}
                }
                local cardsInfo = teamComponent:GetAllCardId(cardTab, true)
                local maxNum = maxNum
                if #cardsInfo > maxNum then
                    for i =  #cardsInfo, maxNum + 1, -1 do
                        table.remove(cardsInfo, i)
                    end
                end
                t1[1].cardsInfo = cardsInfo
                -- t1[1].mergeSkill = 0
                local cardIds = table.serialize(t1)
                RegionQuestMgr:GetInstance():TeamReq({roomSet = cardIds})
            else
                teamComponent:SetTeamByQuestId(self.curLevelId, cardTab, nil, self._teamIndex)
            end
                
            local catBallLimit = BattleHelperConfMgr:GetInstance():IsCatBallLimit(self.curLevelId)
            if self._isShowCatBall and not catBallLimit then
                self:AutoFormationCat()
            end

            self:FillConditions()
        end
    elseif self._isShowCatBall then
        self:AutoFormationCat()
    else
        GameUtils.Toast(localize("当前关卡无法变更队伍阵容"))
    end
end

function UIFightTeamDialog:AutoFormationCat()
    --- 战前编队一键上阵猫球规则；优先上阵排序-猫球星级＞猫球品质＞猫球属性偏向（属性偏向为攻击＞辅助＞防御）
    
    local questId = self.curLevelId
    ---@type CatBallUtils
    local CatBallUtils = import("Game.CatBall.CatBallUtils")
    ---@type TeamCatBallDojo[]
    local teamCats = teamComponent:GetEmptyTeamCat(questId)
    local catBallType2Index = {}
    for index, value in ipairs(teamCats) do
        catBallType2Index[value.catType] = index
        
    end
    CatBallUtils.SortCatBallInAutoFormation(function (dojo, catBallType)
        local index = catBallType2Index[catBallType]
        if index then
            ---@type TeamCatBallDojo
            local teamCatBallDojo = teamCats[index]
            teamCatBallDojo:Fill(dojo)

            catBallType2Index[catBallType] = nil
        end

        return next(catBallType2Index) == nil
    end,questId, self._teamIndex, self.curLevelType)
    
    teamComponent:SetTeamCatByQuestId(questId, teamCats, self._teamIndex)


end

--获取一个最优羁绊卡
function UIFightTeamDialog:GetTeamFettersCard(cardId, team)
    local t = self:GetAllCardsData(true, team)
    t = CardUtils.SortCardBySortType(t, Constants.SortType.CombatPower, true)

    local vo2 = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    --先找特殊羁绊
    for i = 1, table.count(t) do
        local fettersId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(cardId, t[i].cardId)
        --有特殊羁绊
        if fettersId > 0 then
            local isCanChange = teamComponent:IsCanChangeTeamFettersCard(team, t[i].cardId)
            local vo1 = CardConfMgr:GetInstance():GetCardByRefId(t[i].cardId)
            isCanChange = (isCanChange and (checkNumber(vo1.characterId) ~= checkNumber(vo2.characterId)))
            if isCanChange then
                return t[i].id, t[i].cardId
            end
        end
    end

    --特殊羁绊没找到取战斗力最高能上的
    for i = 1, table.count(t) do
        local isCanChange = teamComponent:IsCanChangeTeamFettersCard(team, t[i].cardId)
        local vo1 = CardConfMgr:GetInstance():GetCardByRefId(t[i].cardId)
        isCanChange = (isCanChange and (checkNumber(vo1.characterId) ~= checkNumber(vo2.characterId)))
        if isCanChange then
            return t[i].id, t[i].cardId
        end
    end
    return 0, 0
end

--自动编队
function UIFightTeamDialog:AutoFormation2()
    local restPositionNum = teamComponent:GetMaxSelectNum(self.curLevelId, Constants.ChooseCardStatus.Normal, self._teamIndex) --初始空位数量

    if restPositionNum > 0 then
        if self.isFirstClick then --第一次点击时才与服务器通讯
            self.isFirstClick = true
            --取得所有卡牌
            local cards = self:GetAllCardsData()
            local t = CardUtils.SortCardBySortType(cards, Constants.SortType.CombatPower, false)

            local cdtT = QuestConfMgr:GetInstance():GetQuestConditions(self.curLevelId, nil, self._conditionParas)

            --按照规则筛选后的自动编队的数据
            local cardTab = {}
            for i = table.count(t), 1, -1 do
                if restPositionNum > 0 then
                    local cardData = t[i]
                    local isCanJoinTeam = self:IsCanJoinTeam(cardData, cardTab)
                    if isCanJoinTeam then
                        --机器人队伍  没有会是空
                        local helperTeam = QuestConfMgr:GetInstance():GetQuestHelpers(self.curLevelId)
                        --过滤掉不符合条件的数据
                        if teamComponent:IsCanJoinTeam(cardTab, cardData) and teamComponent:IsCanJoinTeam(helperTeam, cardData) then                      
                            local isSuffice = true
                            for k, v in pairs(cdtT) do
                                --队伍条件不满足 并且单个的满足了
                                if not QuestConfMgr:GetInstance():IsCardDataSufficeCondition(v, cardData, cardTab) then
                                    isSuffice = false
                                    break
                                end
                            end
                            --满足所有条件
                            if isSuffice then
                                --添加到编队中
                                local refId = cardData.id
                                local type = (checkNumber(cardData.isAssistant) == 1 and Constants.TeamMemberType.HelperCard or Constants.TeamMemberType.PlayerCard)
                                table.insert(cardTab, CfUtils.GetTeamMemberDojo{
                                    type = type,
                                    refId = refId
                                })
                                restPositionNum = restPositionNum - 1
                                table.remove(t, i)
                            end

                            if restPositionNum <= 0 then
                                break
                            end
                        end
                    end
                end
            end

            for i = table.count(t), 1, -1 do
                if restPositionNum > 0 then
                    local cardData = t[i]
                    local isCanJoinTeam = self:IsCanJoinTeam(cardData, cardTab)
                    if isCanJoinTeam then
                        --机器人队伍  没有会是空
                        local helperTeam = QuestConfMgr:GetInstance():GetQuestHelpers(self.curLevelId)
                        --过滤掉不符合条件的数据
                        if teamComponent:IsCanJoinTeam(cardTab, cardData) and teamComponent:IsCanJoinTeam(helperTeam, cardData) then                      
                            local isSuffice = false

                            local _t = {}
                            for k, v in pairs(cardTab) do
                                table.insert(_t, v.refId)
                            end
                            for k, v in pairs(cdtT) do
                                --队伍条件不满足 并且单个的满足了
                                if not QuestConfMgr:GetInstance():_CheckCardCondition(v, _t) and QuestConfMgr:GetInstance():IsCardDataSufficeCondition(v, cardData, cardTab) then
                                    isSuffice = true
                                    break
                                end
                            end
                            --满足所有条件
                            if isSuffice then
                                --添加到编队中
                                local refId = cardData.id
                                local type = (checkNumber(cardData.isAssistant) == 1 and Constants.TeamMemberType.HelperCard or Constants.TeamMemberType.PlayerCard)
                                table.insert(cardTab, CfUtils.GetTeamMemberDojo{
                                    type = type,
                                    refId = refId
                                })
                                restPositionNum = restPositionNum - 1
                                table.remove(t, i)
                            end

                            if restPositionNum <= 0 then
                                break
                            end
                        end
                    end
                end
            end

            for i = table.count(t), 1, -1 do
                if restPositionNum > 0 then
                    local cardData = t[i]
                    local isCanJoinTeam = self:IsCanJoinTeam(cardData, cardTab)
                    if isCanJoinTeam then
                        --机器人队伍  没有会是空
                        local helperTeam = QuestConfMgr:GetInstance():GetQuestHelpers(self.curLevelId)
                        --过滤掉不符合条件的数据
                        if teamComponent:IsCanJoinTeam(cardTab, cardData) and teamComponent:IsCanJoinTeam(helperTeam, cardData) then    
                            --添加到编队中
                            local refId = cardData.id
                            local type = (checkNumber(cardData.isAssistant) == 1 and Constants.TeamMemberType.HelperCard or Constants.TeamMemberType.PlayerCard)
  
                            local testT = clone(cardTab)
                            table.insert(testT, CfUtils.GetTeamMemberDojo{
                                type = type,
                                refId = refId
                            })

                            local isSuffice = true
                            for k, v in pairs(cdtT) do
                                local _t = {}
                                for k, v in pairs(cardTab) do
                                    table.insert(_t, v.refId)
                                end
                                --队伍所有条件不满足
                                if not QuestConfMgr:GetInstance():_CheckCardCondition(v, _t) then
                                    isSuffice = false
                                    break
                                end
                            end

                            --满足所有条件
                            if isSuffice then
                                --添加到编队中
                                table.insert(cardTab, CfUtils.GetTeamMemberDojo{
                                    type = type,
                                    refId = refId
                                })
                                restPositionNum = restPositionNum - 1
                                table.remove(t, i)
                            end

                            if restPositionNum <= 0 then
                                break
                            end
                        end
                    end
                end
            end

            if table.count(cardTab) < self._maxTeamMember then
                for i = table.count(cardTab) + 1, self._maxTeamMember do
                    table.insert(cardTab, {})
                end
            end
            teamComponent:SetTeamByQuestId(self.curLevelId, cardTab)
        end
    else
        GameUtils.Toast(localize("当前关卡无法变更队伍阵容"))
    end
end

--- 是否可以加入队伍
---@param data CardDojo @ 要检测是否能上的卡
---@param cardTab CardDojo[] @ 已经上的卡
function UIFightTeamDialog:IsCanJoinTeam(data, cardTab)
    if not data then
        return false
    end
    if self.curLevelType == Constants.IDType.QuestMaze then
        return checkNumber(data.hpPercent) > 0 
    elseif self.curLevelType == Constants.IDType.QuestPatrolMaze then
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local areaDojo = self._patrolMaze.areaDojo
        local mazeCardDojo = areaDojo:GetMazeCard(data.id)
        return mazeCardDojo.hpPercent > 0
    elseif self.curLevelType == Constants.IDType.QuestGachaCoin then  --抽卡副本
        local gachaCoinQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.GachaCoinQuestComponent)
        return (not gachaCoinQuestComponent:IsCardInBlackList(data))
    --elseif self.curLevelType == Constants.IDType.QuestSeniorEquipCopy then
    --    local equipQuestComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.EquipQuestComponent)
    --    --local hpEnergyData = equipQuestComp:GetEquipCopyCardHpEngyData(data.id)
    --
    --    local maxXieLi = checkNumber(equipQuestComp:GetCurQuestCostNum())
    --    --血量大于0
    --    --if checkNumber(hpEnergyData.hpPercent) > 0 then
    --        local curXieli = teamComponent:GetCurTeamXielizhi(cardTab)
    --
    --        local cardXieli = CardUtils.GetCardXielizhi(data.cardId)
    --        if cardXieli <= (maxXieLi - curXieli) then
    --            return true
    --        end
    --    --end
    --    return false
    elseif self.curLevelType == Constants.IDType.QuestTalent then 
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
        local hpEnergyData = comp:GetCardHpEngyData(data.id)
        return checkNumber(hpEnergyData.hpPercent) > 0
    elseif self.curLevelType == Constants.IDType.QuestAdvancedTraining then
        local canUse = true
        local conditionData = QuestConfMgr:GetInstance():GetQuestConditionWithMoreCf(self.curLevelVo.conditionId, self.curLevelVo.conditionValue)
        if conditionData.comparType == Constants.QuestConditionComparType.GreaterThan then
            if checkNumber(data.star) < checkNumber(conditionData.value) then
                canUse = false
            end
        elseif conditionData.comparType == Constants.QuestConditionComparType.LessThan then
            if checkNumber(data.star) > checkNumber(conditionData.value) then
                canUse = false
            end
        end
        return canUse
    elseif self.curLevelType == Constants.IDType.QuestTower then
        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)
        local OverseaTowerUtils = import('Game.UI.FightReady.OverseaTower.OverseaTowerUtils')
        local towerTypeVo = OverseaTowerUtils.GetTowerTypeVo(questVo.type)
        local limitAttr = checkTable(towerTypeVo.limitAttr)
        if next(limitAttr) then
            for _, attrId in ipairs(limitAttr) do
                if checkInt(data.cardId) > 0 then
                    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(data.cardId)
                    if cardVo.attributeType == attrId then
                        return true
                    end
                end
            end
            return false
        end
    elseif self.curLevelType == Constants.IDType.ClubBoss or self.curLevelType == Constants.IDType.QuestChaoticRecall or self.curLevelType == Constants.IDType.Fairyland then
        local isLimitCard = GameUtils.IsLimitCard(self.curLevelId,data.id,self._teamIndex)
        if isLimitCard then
            return false
        end
    end
    return true
end

--根据当前的关卡类型获取所有的卡牌信息
---@param isFetters boolean
---@param team TeamMemberDojo[]
function UIFightTeamDialog:GetAllCardsData(isFetters, team)
    ---@type CardDojo[] @ 全部卡牌数据
    local t = {}
    ---@type CardDojo[] @ 筛选后的卡牌数据
    local cards = {}

    if self.curLevelType == Constants.IDType.QuestMaze then  --迷宫
        ---@type MazeTeamComponent
        local mazeTeamComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MazeTeamComponent, Constants.MazeTeamEntityId)
        t = mazeTeamComp:GetRolesArr()
    elseif self.curLevelType == Constants.IDType.QuestPatrolMaze then  -- 海外夜巡
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local areaDojo = self._patrolMaze.areaDojo
        t = areaDojo:GetAliveCardDojoList()
    elseif self.curLevelType == Constants.IDType.QuestChaoticRecall then
        t = cardComponent:GetAllCardTable()
        for i, v in pairs(t) do
            if not teamComponent:GetTeamCardData(team, v.id) then
                local isInTeam, teamIndex = teamComponent:IsCardInAllTeam(self.curLevelId, v.id)
                if not isInTeam or checkNumber(teamIndex) == checkNumber(self._teamIndex)  then
                    table.insert(cards, v)
                end
            end
        end
        return cards
    else
        t = cardComponent:GetAllCardTable()
    end

    if self.curLevelId == Constants.SpecialQuestId.LadderStruggleId
    or self.curLevelId == Constants.SpecialQuestId.LadderStruggleSingleId 
    or self.curLevelId == Constants.SpecialQuestId.ClubGVGId then
        if not isFetters then
            for k, v in pairs(t) do
                local isInTeam, teamIndex = teamComponent:IsCardInAllTeam(self.curLevelId, v.id)
                if not isInTeam or checkNumber(teamIndex) == checkNumber(self._teamIndex) then
                    table.insert(cards, v)                    
                end
            end
        else
            for k, v in pairs(t) do
                if not teamComponent:GetTeamCardData(team, v.id) then
                    local isInTeam, teamIndex = teamComponent:IsCardInAllTeam(self.curLevelId, v.id)
                    if not isInTeam or checkNumber(teamIndex) == checkNumber(self._teamIndex)  then
                        table.insert(cards, v)
                    end
                end
            end
        end 
        return cards
    end

    --不是选择羁绊会有限制条件
    if not isFetters then
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)
        if vo and checkNumber(vo.roleRestrictions) > 0 then  -- 角色限制
            for k, v in pairs(t) do
                if not QuestConfMgr:GetInstance():CheckCardByTeamLimitId(vo.roleRestrictions, Constants.TeamLimitType.Limit, v.cardId) then
                    table.insert(cards, v)
                end
            end
        else
            cards = t
        end
    else
        for k, v in pairs(t) do
            if not teamComponent:GetTeamCardData(team, v.id) then
                table.insert(cards, v)
            end
        end
    end 

    return cards
end

