---检查关卡卡牌限制
function UIFightTeamDialog:CheckCardLimit(teamTab, checkQuestLimit)
    teamTab = clone(teamTab)
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId) or {}
    local isRefresh = false
    -- 数量限制
    if questVo.roleNun and checkInt(questVo.roleNun) < #teamTab then
        for i, v in ipairs(teamTab) do
            if i > checkInt(questVo.roleNun) then
                teamTab[i] = {}
            end
        end
        isRefresh = true
    end
    
    if not checkQuestLimit then
        -- 第一次进入会检查一次, 自己编辑不需要检查
        local argument = self.controller.Argument.parameters
        if argument and not argument.checkLimit then
            self.controller.Argument.parameters.checkLimit = true
            checkQuestLimit = true
        end
    end
    
    if checkQuestLimit then
        local data, update = self:CheckQuestLimit(teamTab)
        teamTab = data
        isRefresh = isRefresh or update
    end

    if isRefresh then
        teamComponent:SetTeamByQuestId(self.curLevelId, teamTab, nil, self._teamIndex)
    end

    return teamTab
end

---关卡卡牌限制
function UIFightTeamDialog:CheckQuestLimit(teamTab)
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.curLevelId)
    local limitVo = QuestConfMgr:GetInstance():GetQuestTeamLimitVo(checkTable(questVo).roleRestrictions)
    local isRefresh = false
    local isDelete = false
    -- 卡牌限制
    if limitVo then
        local mastT = {}
        local limitT = {}
        for i = 1, 4 do
            -- 只处理卡牌限制
            local type = checkNumber(limitVo["type"..i])
            local armId = checkInt(limitVo["arm"..i])

            if armId > 0 then
                if type == Constants.TeamLimitType.Must then
                    table.insert(mastT, armId)
                elseif type == Constants.TeamLimitType.Limit then
                    table.insert(limitT, armId)
                end
            end
        end
        
        local newT = {}
        local usableT = {}
        
        for _, teamData in ipairs(teamTab) do
            if checkInt(teamData.cardId) > 0 then
                if checkInt(teamData.type) == Constants.TeamMemberType.QuestLockHelperCard then
                    -- 机器人是不可被替换的的
                    table.insert(newT, teamData)
                    teamData = {}
                else
                    if not table.indexof(limitT, teamData.cardId) then
                        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(teamData.cardId)
                        local roleId = checkInt(cardVo.characterId)
                        -- 清理角色占用
                        local roleConflict = false
                        for _, v in ipairs(newT) do
                            local tCardVo = CardConfMgr:GetInstance():GetCardByRefId(v.cardId)
                            local tRoleId = checkInt(tCardVo.characterId)
                            if roleId == tRoleId then
                                roleConflict = true
                                break
                            end
                        end
                        if not roleConflict then
                            for _, v in ipairs(mastT) do
                                local tCardVo = CardConfMgr:GetInstance():GetCardByRefId(v)
                                local tRoleId = checkInt(tCardVo.characterId)
                                if roleId == tRoleId then
                                    roleConflict = true
                                    break
                                end
                            end
                        end

                        if not roleConflict and QuestConfMgr:CheckCardTeamLimitType(self.curLevelId, Constants.TeamLimitType.Limit, teamData.cardId) then
                            roleConflict = true
                        end

                        if not roleConflict then
                            if table.indexof(mastT, teamData.fettersCardId) then
                                teamData.fettersCardId = 0
                                teamData.fettersId = 0
                            end
                            table.insert(usableT, teamData)
                        end
                    end
                end
            end
        end

        for _, armId in ipairs(mastT) do
            local refId = cardComponent:GetIdByCardId(armId)
            if refId then
                local dojo = CfUtils.GetTeamMemberDojo({
                    type = Constants.TeamMemberType.PlayerCard,
                    refId = refId
                })
                table.insert(newT, dojo)
            end
        end

        if #newT < teamComponent:GetMaxTeamMemberNumByQuestId(self.curLevelId) then
            local num = teamComponent:GetMaxTeamMemberNumByQuestId(self.curLevelId) - #newT
            for i = 1, num do
                if usableT[i] then
                    table.insert(newT, usableT[i])
                else
                    table.insert(newT, {})
                end
            end
        end
        
        teamTab = newT
        isRefresh = true
    end

    -- 处理爬塔编队，因为在线上存在数据后修改，所以要处理脏数据
    if self.curLevelType == Constants.IDType.QuestTower then
        local OverseaTowerUtils = import('Game.UI.FightReady.OverseaTower.OverseaTowerUtils')
        local towerTypeVo = OverseaTowerUtils.GetTowerTypeVo(questVo.type)
        local limitAttr = checkTable(towerTypeVo.limitAttr)
        if next(limitAttr) then
            for i, teamData in ipairs(teamTab) do
                if next(teamData) then
                    local usable = false
                    for _, attrId in ipairs(limitAttr) do
                        if checkInt(teamData.cardId) > 0 then
                            local cardVo = CardConfMgr:GetInstance():GetCardByRefId(teamData.cardId)
                            if cardVo.attributeType == attrId then
                                usable = true
                                break
                            end
                        end
                    end
                    if not usable then
                        teamTab[i] = {}
                        isDelete = true
                        isRefresh = true
                    end
                end
            end
        end
    end

    -- 清理空位
    if isDelete then
        local finT = {}
        for _, v in ipairs(teamTab) do
            if next(v) then
                table.insert(finT, v)
            end
        end

        for i = 1, #teamTab - #finT do
            table.insert(finT, {})
        end
        teamTab = finT
    end

    return teamTab, isRefresh
end

--- 清理情绪共鸣特效
function UIFightTeamDialog:ClearEmotionFX()
    for i = 1, 5 do
        local teamGo = self["TeamNode"..i]
        ---@type UIFightTeamTeamNode
        local scr = CfUtils.GetLuaScr(teamGo, UIFightTeamTeamNode)
        if scr then
            scr:CloseEmotionBonusFlyFX()
        end
    end
end

--- 引导使用 
---检查关卡是否是指定id并且战力不满足
function UIFightTeamDialog:CheckCombatEffTipsGuideCondition(questId)
    return questId == self.curLevelId and checkNumber(self._power) < checkNumber(self.curLevelVo.proposalLevel)
end

--- 引导使用 
---检查关卡是否是指定id并且战力不满足
function UIFightTeamDialog:CheckTeamCardCount(count)
    local cardCount = 0
    for index, value in ipairs(self.teamTab) do
        if next(value) ~= nil then
            cardCount = cardCount + 1
        end
        if cardCount == count then
            return true
        end
    end
    return false
end

--- 刷新情绪共鸣特效
function UIFightTeamDialog:RefreshEmotionBonusFX()
    local teams = teamComponent:GetTeamByQuestId(self.curLevelId, self._teamIndex)

    -- 刷新右上角icon
    GameUtils.RefreshLineupBonusNode(self.FightTeamBonusNode, teams, true, true)

    -- 计算共鸣的情绪 id列表
    local emotionBonusDict = CardUtils.CalculateEmotionBonusDict(teams)

    for i = 1, table.count(teams) do
        local teamGo = self["TeamNode"..i]
        ---@type UIFightTeamTeamNode
        local scr = CfUtils.GetLuaScr(teamGo, UIFightTeamTeamNode)
        if scr then
            local showEmotionBonus = CardUtils.ConsumeEmotionBonusDict(teams[i], emotionBonusDict)
            scr:SetEmotionBonusLoopFX(showEmotionBonus)
            if showEmotionBonus then
                scr:ShowEmotionBonusFlyFX(self.FightTeamBonusNode.gameObject)
            else
                scr:CloseEmotionBonusFlyFX()
            end
        end
    end
end

function UIFightTeamDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            -- Events.RemoveListener(Constants.EventNames.SkillCompoundChange, self.EventSkillCompoundChange)
            Events.RemoveListener(Constants.EventNames.RefreshTeamCat, self.EventRefreshTeamCat)
            Events.RemoveListener(Constants.EventNames.RefeshTeamMember, self.EventRefeshTeamMember)
            Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.EventEveryThingChangeEventName)
            Events.RemoveListener(Constants.EventNames.ReSelectLevel, self.EventReSelectLevel)
            Events.RemoveListener(Constants.EventNames.RegionTeamKickout, self.EventRegionTeamKickout)
            Events.RemoveListener(Constants.EventNames.ContinueBattle, self.EventContinueBattle)
        end
        CfUtils.RefreshTopCommon()
        --CfUtils.RefreshTopGoods(nil)

        self:ClearEmotionFX()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

