function UIFightTeamDialog:OnClickExplainButtonHandler_()
    local dataList = {}
    if self.curLevelType == Constants.IDType.QuestNightCatTower or self.curLevelType == Constants.IDType.QuestNightCatBoss then
        ---@type NightCatQuestComponent
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.NightCatQuestComponent)
        local buffAddPower = comp:GetEquipBuffAddPower()
        dataList = {
            { name = localize('编队战力'), value = self._power },
            { name = localize('增益加成'), value = buffAddPower },
        }
    elseif self.curLevelType == Constants.IDType.MournBoss or self.curLevelType == Constants.IDType.MournTower then
        ---@type ActivityMournUtils
        local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')
        local buffAddPower = ActivityMournUtils.GetEquipBuffAddPower()
        dataList = {
            { name = localize('编队战力'), value = self._power },
            { name = localize('增益加成'), value = buffAddPower },
        }
    end
    GameUtils.ShowCommonPowerTips(self.BtnExplain.gameObject, localize('战力组成'), dataList, true, false)
end


